int main(void) {
    long long N, H, D;
    if (scanf("%lld %lld %lld", &N, &H, &D) != 3) return 0;

    /* 
       At any step, all squares with the current minimum height can be raised
       to any height in [current_max, current_max + D].

       Consider one "round": all squares currently at the minimum height m
       are eventually raised before any square can exceed them again.
       During that round, each of those squares independently chooses a final
       height in [M, M + D], where M is the current maximum before the round.

       Starting from all 0, after the first round all N squares choose heights
       in [0, D]. Then squares at the new minimum are processed, etc.

       A standard equivalent characterization is:
       the process builds each square's height from 0 to H by increments where
       the next attained level for a square can jump ahead by at most D beyond
       the current global frontier. This yields the same count as the number of
       ways to assign, for each of the H layers, a nonempty subset of squares
       that "finish" that layer, with a D-step memory.

       The resulting count is:
         if D = 0: only possible when H = 0 or all remain equal each time,
                   so exactly 1 way.
         if N = 1: exactly 1 way if H <= D or by repeated single-square raises;
                   in fact always 1.

       For general N,D,H, the count is:
         prod_{i=0}^{H-1} ((D+1)^N - i^0...)  -- not correct in general.

       We instead use the known DP for this process:
       Let dp[x] = number of ways to reach a state where the minimum height is x
       and all heights are in [x, x + D].
       Transition from x to x+1 depends only on which squares are exactly x.

       Represent a state by a bitmask of relative heights compressed by whether
       a square is at the minimum or above it. Because squares are symmetric,
       only the count k of squares at the minimum matters.
       From such a state, those k squares are each raised to one of D+1 levels
       relative to current minimum+1 ... current minimum+D+1, but at least one
       must be raised to exactly current minimum+1 for the new minimum to become
       x+1. The number of choices creating exactly t squares at the new minimum
       is C(k,t) * D^(k-t), for 1 <= t <= k.

       Thus if f_h[k] = ways after processing up to minimum h with exactly k
       squares at height h, then:
         f_0[N] = 1
         f_{h+1}[t] += sum_{k=t..N} f_h[k] * C(k,t) * D^(k-t)
       Answer = f_H[N], because at final minimum H all squares must be at H.

       This DP is O(H N^2). 
    */

    if (H == 0) {
        printf("1\n");
        return 0;
    }
    if (N == 1) {
        printf("1\n");
        return 0;
    }

    long long *fact = (long long*)malloc((N + 1) * sizeof(long long));
    long long *invfact = (long long*)malloc((N + 1) * sizeof(long long));
    long long *powD = (long long*)malloc((N + 1) * sizeof(long long));
    long long *dp = (long long*)calloc(N + 1, sizeof(long long));
    long long *ndp = (long long*)calloc(N + 1, sizeof(long long));

    fact[0] = 1;
    for (long long i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = mod_pow(fact[N], MOD - 2);
    for (long long i = N; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    powD[0] = 1;
    for (long long i = 1; i <= N; i++) powD[i] = powD[i - 1] * (D % MOD) % MOD;

    dp[N] = 1;

    for (long long h = 0; h < H; h++) {
        memset(ndp, 0, (N + 1) * sizeof(long long));
        for (long long k = 1; k <= N; k++) {
            if (dp[k] == 0) continue;
            for (long long t = 1; t <= k; t++) {
                long long comb = fact[k] * invfact[t] % MOD * invfact[k - t] % MOD;
                long long ways = comb * powD[k - t] % MOD;
                ndp[t] = (ndp[t] + dp[k] * ways) % MOD;
            }
        }
        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    printf("%lld\n", dp[N] % MOD);

    free(fact);
    free(invfact);
    free(powD);
    free(dp);
    free(ndp);
    return 0;
}

