        int[] init = new int[N];
        System.out.println(solve(init));
    }

    static long solve(int[] state) {
        int[] sorted = state.clone();
        Arrays.sort(sorted);
        if (sorted[N-1] == H && sorted[0] == H) return 1;
        String key = Arrays.toString(sorted);
        if (memo.containsKey(key)) return memo.get(key);
        int minV = sorted[0], maxV = sorted[N-1];
        int cnt = 0;
        for (int x : sorted) if (x == minV) cnt++;
        long ans = 0;
        for (int v = maxV; v <= maxV + D && v <= H; v++) {
            int[] next = sorted.clone();
            next[0] = v;
            Arrays.sort(next);
            ans = (ans + cnt * solve(next)) % MOD;
        }
        memo.put(key, ans);
        return ans;
    }
}

