/*
We count the number of valid sequences of operations.

Interpretation used:
- There are N columns, initially 0.
- One operation chooses a column whose current height is minimum among all columns.
- If current maximum height is M, after the operation that chosen column's height must become in [M, M + D].
- We repeat until all columns become exactly H.

Key observation:
If we process columns independently by the order in which each column is chosen, then at any time
the chosen column is one of the current minima. Let the heights of columns be built as increasing
"levels". A column can jump from some level x to some higher level y, but only when x is currently
the global minimum and y <= current maximum + D.

This leads to a DP on the sorted multiset of attained heights.
A standard way is to think level by level:
Suppose currently every column height lies in [t, t + D], and at least one column is exactly t.
All columns of height t must be raised before the minimum can increase. Each such column can be raised
to any value in [t+1, t+D]. Relative to t, this is equivalent for every minimum-column to choose an
increment s in [1, D]. After all c minimum-columns are processed, the new multiset of offsets
(among all N columns) is obtained. Shifting by the new minimum repeats the same process.

This is exactly counting paths of a finite-state automaton over states:
state = counts of columns at offsets 0..D, where count[0] > 0 and sum = N.
One "round" processes all count[0] columns, each choosing a target offset 1..D.
Then we subtract the new minimum positive offset from all offsets to normalize.

Height increases by that subtracted amount. We need total increase exactly H.

So:
- Build all normalized states.
- For each state, enumerate all possible resulting states after one round, with associated
  increase delta and multiplicity.
- DP over total height 0..H on states.

Number of states is compositions of N into D+1 parts with first part positive:
C(N + D - 1, D), manageable for intended constraints (the original problem has small D).
*/

public class Main {
    static final long MOD = 1_000_000_007L;

    static int N, H, D;

    static class State {
        int[] c; // size D+1, c[0] > 0, sum N
        State(int[] c) { this.c = c; }
    }

    static class Trans {
        int to;
        int delta;
        long ways;
        Trans(int to, int delta, long ways) {
            this.to = to;
            this.delta = delta;
            this.ways = ways;
        }
    }

    static ArrayList<State> states = new ArrayList<>();
    static HashMap<String, Integer> idMap = new HashMap<>();
    static ArrayList<Trans>[] graph;

    static String key(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(a[i]);
        }
        return sb.toString();
    }

    static void genStates(int idx, int rem, int[] cur) {
        if (idx == D) {
            cur[D] = rem;
            if (cur[0] > 0) {
                int[] arr = cur.clone();
                int id = states.size();
                states.add(new State(arr));
                idMap.put(key(arr), id);
            }
            return;
        }
        int start = (idx == 0 ? 1 : 0);
        for (int v = start; v <= rem; v++) {
            cur[idx] = v;
            genStates(idx + 1, rem - v, cur);
        }
    }

    static void buildTransitionsForState(int sid) {
        State st = states.get(sid);
        int c0 = st.c[0];

        // We distribute c0 minimum-columns to target offsets 1..D.
        // Let add[j] = how many of those go to offset j.
        int[] add = new int[D + 1];
        HashMap<Long, Long> acc = new HashMap<>();

        dfsAssign(sid, st.c, c0, 1, add, acc);

        ArrayList<Trans> list = new ArrayList<>();
        for (Map.Entry<Long, Long> e : acc.entrySet()) {
            long packed = e.getKey();
            long ways = e.getValue();

            int delta = (int)(packed >>> 32);
            int to = (int)(packed & 0xffffffffL);
            list.add(new Trans(to, delta, ways));
        }
        graph[sid] = list;
    }

    static void dfsAssign(int sid, int[] base, int rem, int pos, int[] add, HashMap<Long, Long> acc) {
        if (pos == D) {
            add[D] = rem;
            processAssignment(base, add, acc);
            return;
        }
        for (int v = 0; v <= rem; v++) {
            add[pos] = v;
            dfsAssign(sid, base, rem - v, pos + 1, add, acc);
        }
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long[] fact, invFact;

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    static void initComb(int max) {
        fact = new long[max + 1];
        invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    }

    static void processAssignment(int[] base, int[] add, HashMap<Long, Long> acc) {
        // multiplicity: multinomial c0! / prod add[j]!
        int c0 = base[0];
        long ways = fact[c0];
        for (int j = 1; j <= D; j++) ways = ways * invFact[add[j]] % MOD;

        int[] tmp = new int[D + 1];
        for (int i = 1; i <= D; i++) tmp[i] = base[i] + add[i];

        int delta = -1;
        for (int i = 1; i <= D; i++) {
            if (tmp[i] > 0) {
                delta = i;
                break;
            }
        }
        // Since all c0 columns moved to 1..D, delta always exists.

        int[] nxt = new int[D + 1];
        for (int i = delta; i <= D; i++) nxt[i - delta] = tmp[i];

        String k = key(nxt);
        Integer to = idMap.get(k);
        long pack = (((long)delta) << 32) | (to & 0xffffffffL);
        acc.put(pack, (acc.getOrDefault(pack, 0L) + ways) % MOD);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        H = fs.nextInt();
        D = fs.nextInt();

        genStates(0, N, new int[D + 1]);
        graph = new ArrayList[states.size()];

        initComb(N);

        for (int i = 0; i < states.size(); i++) buildTransitionsForState(i);

        // Initial state: all N columns at same height => normalized counts [N,0,...,0]
        int[] initArr = new int[D + 1];
        initArr[0] = N;
        int init = idMap.get(key(initArr));

        long[][] dp = new long[H + 1][states.size()];
        dp[0][init] = 1;

        for (int h = 0; h <= H; h++) {
            for (int s = 0; s < states.size(); s++) {
                long cur = dp[h][s];
                if (cur == 0) continue;
                for (Trans tr : graph[s]) {
                    int nh = h + tr.delta;
                    if (nh <= H) {
                        dp[nh][tr.to] = (dp[nh][tr.to] + cur * tr.ways) % MOD;
                    }
                }
            }
        }

        // Final state must also be all equal, i.e. [N,0,...,0], at total height H.
        System.out.println(dp[H][init] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

