#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, H, D;
    cin >> N >> H >> D;

    // dp[a][b]:
    // after processing some levels, among N columns,
    // a columns are at current minimum level,
    // b columns are above minimum but not more than D above it.
    //
    // We process level by level from 0 to H-1.
    // At each level, some of the a minimum columns are raised above the minimum.
    // Let x be the number of such columns.
    // Then next state becomes:
    //   new_a = N - x
    //   new_b = x
    //
    // But a column can stay above the minimum for at most D levels.
    // Therefore when advancing one level, the number of columns that were already
    // above minimum for D levels must have returned to minimum. This is captured
    // by remembering only counts over a sliding window of size D.
    //
    // A simpler equivalent formulation:
    // Let f[t][k] = number of ways after t levels such that exactly k columns
    // are chosen to be raised at level t (thus becoming above the new minimum).
    // The validity condition is that for every consecutive D+1 levels,
    // no column can be chosen in all of them; equivalently each column must be
    // skipped at least once in every window of length D+1.
    //
    // This leads to the standard transfer:
    // if during the last D levels, total chosen counts sum to s,
    // then at next level we may choose x columns among the N-s columns currently
    // at minimum, and among the s columns already above minimum we may choose none
    // (they cannot be chosen again since operation only applies to minimum columns).
    //
    // We only need counts of how many columns were chosen in each of last D levels.
    // State compression by total sum is enough because columns are indistinguishable
    // and transitions depend only on how many are currently above minimum.
    //
    // Let dp[len][s] after processing some levels with window length len=min(t,D):
    // s = number of columns currently above minimum.
    // Transition at each new level:
    // choose x among N-s minimum columns to raise: C(N-s, x)
    // new above-minimum count becomes s + x - expired,
    // where expired is the number chosen exactly D levels ago.
    //
    // To track expiration exactly, we need the whole queue of last D choices.
    // Since constraints are not provided here, use map-based DP over vectors.
    //
    // State = last up to D values of chosen counts.
    // Transition multiplies by C(available, x), where available = N - sum(state).
    //
    // Final condition after H levels: all columns at height H, meaning after the
    // last level no column is above minimum, i.e. sum(state)=0.
    //
    // This matches the process exactly.

    vector<vector<long long>> C(N + 1, vector<long long>(N + 1, 0));
    for (int i = 0; i <= N; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    map<vector<int>, long long> dp, ndp;
    dp[vector<int>()] = 1;

    for (int step = 0; step < H; step++) {
        ndp.clear();
        for (auto &it : dp) {
            const vector<int>& state = it.first;
            long long ways = it.second;

            int s = 0;
            for (int v : state) s += v;

            int available = (int)N - s;
            for (int x = 0; x <= available; x++) {
                vector<int> ns = state;
                ns.push_back(x);
                if ((int)ns.size() > D) ns.erase(ns.begin());

                long long add = ways * C[available][x] % MOD;
                ndp[ns] = (ndp[ns] + add) % MOD;
            }
        }
        dp.swap(ndp);
    }

    long long ans = 0;
    for (auto &it : dp) {
        int s = 0;
        for (int v : it.first) s += v;
        if (s == 0) {
            ans = (ans + it.second) % MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}
